13	 * Says in one sentence what one documented symbol is.
14	 *
15	 * This is what a page is previewed by rather than what it is read by: the
16	 * summary line its author wrote is the sentence, and a symbol documented
17	 * with nothing is named by what it is and where it lives, so a shared link
18	 * is never previewed by an empty description.
19	 */
20	final class SymbolDescription
21	{
22	    /**
23	     * Describes one class, interface, trait, or enum.
24	     */
25	    public function ofClassLike(ClassLikeDoc $classLike): string
26	    {
27	        $summary = $classLike->docBlock !== null ? $classLike->docBlock->summary : '';
28	        if ($summary !== '') {
29	            return $summary;
30	        }
31	
32	        return sprintf('The %s %s of the %s package.', $classLike->kind, $classLike->fqcn, $classLike->packageName);
33	    }
