18	/**
19	 * Measures and breaks the lines the social preview card is drawn from.
20	 *
21	 * The card is drawn from what a project happens to be called, so nothing
22	 * about its text is known in advance: the type is measured against the
23	 * font it will be drawn with, shrunk until the longest line fits the card,
24	 * and broken into the lines that are left.
25	 */
26	final class SocialCardText
27	{
28	    /**
29	     * Returns how wide one line of text is, in pixels, at one size.
30	     *
31	     * Text that cannot be measured is reported as empty rather than as an
32	     * error: a card without a subtitle is still a card.
33	     */
34	    public function width(string $font, float $size, string $text): int
35	    {
36	        if ($text === '') {
37	            return 0;
38	        }
39	
40	        $box = imagettfbbox($size, 0.0, $font, $text);
41	        if ($box === false) {
42	            return 0;
43	        }
44	
45	        $left = $box[0];
46	        $right = $box[2];
47	        if (!is_int($left) || !is_int($right)) {
48	            return 0;
49	        }
50	
51	        return abs($right - $left);
52	    }
53	
54	    /**
55	     * Returns the largest whole size at which one line fits a width.
56	     *
57	     * @param int $largest the size the text is set in when it fits
58	     * @param int $smallest the size below which it is broken instead of shrunk
59	     */
60	    public function fit(string $font, string $text, int $maxWidth, int $largest, int $smallest): int
61	    {
62	        for ($size = $largest; $size > $smallest; $size--) {
63	            if ($this->width($font, (float) $size, $text) <= $maxWidth) {
64	                return $size;
65	            }
66	        }
67	
68	        return $smallest;
69	    }
70	
71	    /**
72	     * Breaks text into the lines that fit a width, at most a number of them.
73	     *
74	     * The last line of a text that does not fit ends in an ellipsis, so a
75	     * reader is never left believing they read a whole sentence.
76	     *
77	     * @return list<string>
78	     */
79	    public function wrap(string $font, float $size, string $text, int $maxWidth, int $maxLines): array
80	    {
81	        $lines = $this->lines($font, $size, $text, $maxWidth);
82	        if (count($lines) <= $maxLines) {
83	            return $lines;
84	        }
85	
86	        $kept = array_slice($lines, 0, $maxLines);
87	        $last = array_pop($kept);
88	        if ($last === null) {
89	            return [];
90	        }
91	
92	        $kept[] = $this->shortened($font, $size, $last, $maxWidth);
93	
94	        return $kept;
95	    }
96	
97	    /**
98	     * Breaks text into every line it occupies at one size.
99	     *
100	     * @return list<string>
101	     */
102	    public function lines(string $font, float $size, string $text, int $maxWidth): array
103	    {
104	        $words = preg_split('/\s+/', trim($text), -1, PREG_SPLIT_NO_EMPTY);
105	        if ($words === false || $words === []) {
106	            return [];
107	        }
108	
109	        $lines = [];
110	        $line = '';
111	        foreach ($words as $word) {
112	            $candidate = $line === '' ? $word : $line . ' ' . $word;
113	            if ($line !== '' && $this->width($font, $size, $candidate) > $maxWidth) {
114	                $lines[] = $line;
115	                $line = $word;
116	
117	                continue;
118	            }
119	
120	            $line = $candidate;
121	        }
122	
123	        $lines[] = $line;
124	
125	        return $lines;
126	    }
127	
128	    /**
129	     * Returns one line with an ellipsis, shortened until it fits a width.
130	     */
131	    public function shortened(string $font, float $size, string $line, int $maxWidth): string
132	    {
133	        $characters = preg_split('//u', $line, -1, PREG_SPLIT_NO_EMPTY);
134	        if ($characters === false || $characters === []) {
135	            return $line;
136	        }
137	
138	        while ($characters !== [] && $this->width($font, $size, implode('', $characters) . '…') > $maxWidth) {
139	            array_pop($characters);
140	        }
141	
142	        return implode('', $characters) . '…';
143	    }
144	}
